import heapq

def match(orders):
    trades = []
    # order_info[id] = dict with side, price, qty remaining, active
    order_info = {}
    arrival_counter = 0
    arrival_time = {}

    # heaps: buy_heap entries (-price, arrival, id), sell_heap entries (price, arrival, id)
    buy_heap = []
    sell_heap = []

    def clean_buy_heap():
        while buy_heap:
            neg_price, arr, oid = buy_heap[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        arrival_counter += 1
        arr = arrival_counter

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sell_price, sell_arr, sell_id = sell_heap[0]
                if typ != 'market' and price is not None and sell_price > price:
                    break
                sell_info = order_info[sell_id]
                trade_qty = min(remaining, sell_info['qty'])
                trades.append([oid, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                sell_info['qty'] -= trade_qty
                if sell_info['qty'] <= 0:
                    sell_info['active'] = False
                    heapq.heappop(sell_heap)
                # else keep in heap, it's still at front but qty reduced; loop will re-check
                # if remaining becomes 0, loop exits

            # after matching, if limit and remaining > 0, rest it
            if typ == 'limit' and remaining > 0:
                order_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                heapq.heappush(buy_heap, (-price, arr, oid))
            else:
                # store minimal info in case of cancel attempts later (does nothing anyway)
                order_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': False}

        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                neg_price, buy_arr, buy_id = buy_heap[0]
                buy_price = -neg_price
                if typ != 'market' and price is not None and buy_price < price:
                    break
                buy_info = order_info[buy_id]
                trade_qty = min(remaining, buy_info['qty'])
                trades.append([buy_id, oid, buy_price, trade_qty])
                remaining -= trade_qty
                buy_info['qty'] -= trade_qty
                if buy_info['qty'] <= 0:
                    buy_info['active'] = False
                    heapq.heappop(buy_heap)

            if typ == 'limit' and remaining > 0:
                order_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                heapq.heappush(sell_heap, (price, arr, oid))
            else:
                order_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': False}

    return trades

